+    }
+
+    fn events(raw: &[u8]) -> Vec<(String, Value)> {
+        std::str::from_utf8(raw)
+            .unwrap()
+            .split("\n\n")
+            .filter(|b| !b.is_empty())
+            .map(|b| {
+                let mut l = b.lines();
+                let ev = l
+                    .next()
+                    .unwrap()
+                    .strip_prefix("event: ")
+                    .unwrap()
+                    .to_owned();
+                let data = serde_json::from_str(l.next().unwrap().strip_prefix("data: ").unwrap())
+                    .unwrap();
+                (ev, data)
+            })
+            .collect()
+    }
+
+    const USAGE: &str =
+        r#"{"prompt_tokens":10,"completion_tokens":1,"prompt_tokens_details":{"cached_tokens":6}}"#;
