+        for c in chunks {
+            let (a, b) = c.as_bytes().split_at(c.len() / 2);
+            raw.extend(s.feed(a));
+            raw.extend(s.feed(b));
+        }
+        raw.extend(s.finish());
+        let evs = events(&raw);
+        for (ev, data) in &evs {
+            assert_eq!(data["type"], ev.as_str(), "event name must equal data.type");
+        }
+        evs
+    }
+
+    #[test]
+    fn thinking_then_text() {
