+
+    #[test]
+    fn tool_use_stream_and_stop_sequence() {
+        let evs = run(&[
+            chunk(
+                json!({"tool_calls": [{"index": 0, "id": "call_1",
+                        "function": {"name": "get_weather", "arguments": ""}}]}),
